/** The command palette's list keys (pure, so the account's command logic and its tests share them). */
/** One step through a list, wrapping at the ends. */
export function moveIndex(length: number, current: number, dir: 1 | -1): number {
  if (length <= 0) return 0;
  return (current + dir + length) % length;
}

/** One step through a row's chips (stops at the ends). */
export function moveChip(count: number, current: number, dir: 1 | -1): number {
  if (count <= 1) return 0;
  return Math.max(0, Math.min(count - 1, current + dir));
}
